DO $stage$ DECLARE j jsonb := $payload$[{"language":"es","slug":"zwiebelkuchen-tarta-cebolla","public_path":"/zwiebelkuchen-tarta-cebolla","title":"Zwiebelkuchen: tarta alemana de cebolla con masa casera","excerpt":"Tarta alemana de cebolla con base de masa de levadura, tocineta y crema agria. Zwiebelkuchen para un molde de 28 cm, con fermentación y reposos incluidos.","summary":"Tarta alemana de cebolla con base de masa de levadura, tocineta y crema agria. Zwiebelkuchen para un molde de 28 cm, con fermentación y reposos incluidos.","notes":"<p>Los tiempos se suman sin descontar tareas que puedas solapar. Usa levadura de panadería, no polvo de hornear. La alcaravea no es comino: si falta, omítela en vez de sustituirla sin más. Contiene trigo, leche y huevo. Refrigera las sobras antes de 2 horas y consúmelas en 3 días; recalienta bien el centro.</p><h2>También puedes preparar</h2><ul><li><a href=\"/tartiflette-reblochon-patatas\">Tartiflette de patatas con reblochon y bacon</a></li><li><a href=\"/focaccia-sin-amasado-romero\">Focaccia de romero sin amasado, con fermentación en frío</a></li></ul>","content_html":"<p>Tarta alemana de cebolla con base de masa de levadura, tocineta y crema agria. Zwiebelkuchen para un molde de 28 cm, con fermentación y reposos incluidos.</p><p>Los tiempos se suman sin descontar tareas que puedas solapar. Usa levadura de panadería, no polvo de hornear. La alcaravea no es comino: si falta, omítela en vez de sustituirla sin más. Contiene trigo, leche y huevo. Refrigera las sobras antes de 2 horas y consúmelas en 3 días; recalienta bien el centro.</p><h2>También puedes preparar</h2><ul><li><a href=\"/tartiflette-reblochon-patatas\">Tartiflette de patatas con reblochon y bacon</a></li><li><a href=\"/focaccia-sin-amasado-romero\">Focaccia de romero sin amasado, con fermentación en frío</a></li></ul>","ingredients":[{"name":"Harina de trigo común","amount":"300","unit":"g"},{"name":"Leche entera","amount":"150","unit":"ml"},{"name":"Levadura seca de panadería","amount":"5","unit":"g"},{"name":"Azúcar","amount":"5","unit":"g"},{"name":"Mantequilla sin sal","amount":"30","unit":"g"},{"name":"Sal, repartida entre masa y relleno","amount":"6","unit":"g"},{"name":"Cebolla pelada","amount":"900","unit":"g"},{"name":"Tocineta en dados","amount":"100","unit":"g"},{"name":"Crema agria con 18–20 % de grasa","amount":"200","unit":"g"},{"name":"Huevos, peso sin cáscara","amount":"100","unit":"g"},{"name":"Semillas de alcaravea","amount":"2","unit":"g"},{"name":"Pimienta negra molida","amount":"0.5","unit":"g"}],"steps":[{"title":"Amasa la base","content":"Mezcla la harina, la levadura, el azúcar y 4 g de sal. Incorpora la leche templada y la mantequilla blanda; amasa 8–10 minutos hasta obtener una masa elástica.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Amasa la base"},{"title":"Deja fermentar","content":"Forma una bola, tapa el bol y deja fermentar unos 60 minutos en un lugar templado, hasta que aumente claramente de volumen. El frío puede alargar el tiempo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Deja fermentar"},{"title":"Corta el relleno","content":"Corta los 900 g de cebolla en tiras finas y la tocineta en dados pequeños. Pesa los demás ingredientes antes de encender la sartén.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Corta el relleno"},{"title":"Cocina y enfría la cebolla","content":"Dora la tocineta 5 minutos en una sartén amplia. Añade la cebolla y cocina a fuego medio-bajo unos 15 minutos, hasta ablandarla sin oscurecerla. Deja templar 10 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Cocina y enfría la cebolla"},{"title":"Forra el molde","content":"Cubre con la masa la base y los lados de un molde desmontable de 28 cm con papel en el fondo. Forma un borde de 3 cm y deja reposar 15 minutos. Precalienta el horno a 180 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Forra el molde"},{"title":"Mezcla la crema","content":"Bate el huevo con la crema agria, la alcaravea, la pimienta y los 2 g de sal restantes. Incorpora la cebolla y la tocineta ya templadas, nunca muy calientes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Mezcla la crema"},{"title":"Rellena y hornea","content":"Reparte el relleno sobre la masa. Hornea a 180 °C, calor arriba y abajo, durante 40–45 minutos, hasta que el centro esté cuajado y la base cocida. Protege el borde si se dora antes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Rellena y hornea"},{"title":"Reposa y corta","content":"Espera 10 minutos antes de desmoldar. Corta ocho porciones con un cuchillo de sierra y sirve templado, con el relleno firme y jugoso.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera: Reposa y corta"}],"category":"Panes y masas","course":"Panes y masas","cuisine":"Alemana","difficulty":"Media","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera"}],"video_urls":[],"keywords":["Zwiebelkuchen: tarta alemana de cebolla con masa casera","Harina de trigo común","Leche entera"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"1 de 8 porciones","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de referencias por peso, dividida entre las porciones; todos los ingredientes principales contabilizados.","note":"Estimación orientativa, no medición del plato cocinado. Las marcas y el escurrido cambian los valores; los nutrientes sin dato completo no se muestran. Referencias genéricas para mostaza preparada, crema, boniato, aceite y chocolate; las variedades y marcas concretas pueden diferir."},"seo":{"title":"Zwiebelkuchen: tarta alemana de cebolla con masa casera","description":"Tarta alemana de cebolla con base de masa de levadura, tocineta y crema agria. Zwiebelkuchen para un molde de 28 cm, con fermentación y reposos incluidos.","image_alt":"Zwiebelkuchen: tarta alemana de cebolla con masa casera","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar hojaldre?","a":"Esta formulación utiliza masa fermentada. El hojaldre da otra base y necesita otros tiempos; no es una sustitución directa."},{"q":"¿Hay que caramelizar la cebolla?","a":"No. Debe quedar tierna y clara; un dorado oscuro cambia el sabor y puede resecar el relleno."},{"q":"¿Puedo hacerlo el día anterior?","a":"Sí. Hornea, enfría y refrigera tapado. Recalienta las porciones y no dejes el relleno con huevo crudo a temperatura ambiente."}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"zwiebelkuchen-hefeteig-speck","public_path":"/de/zwiebelkuchen-hefeteig-speck","title":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne","excerpt":"Herzhafter Zwiebelkuchen mit selbst gemachtem Hefeboden, weich gedünsteten Zwiebeln, Speck und Kümmel. Für eine 28-cm-Springform und acht Stücke.","summary":"Herzhafter Zwiebelkuchen mit selbst gemachtem Hefeboden, weich gedünsteten Zwiebeln, Speck und Kümmel. Für eine 28-cm-Springform und acht Stücke.","notes":"<p>Die Gesamtzeit addiert alle Arbeitsschritte, auch wenn einige parallel möglich sind. Backhefe verwenden, kein Backpulver. Kümmel ist kein Kreuzkümmel; bei Bedarf weglassen statt beliebig ersetzen. Enthält Weizen, Milch und Ei. Reste innerhalb von 2 Stunden kühlen und innerhalb von 3 Tagen verbrauchen; beim Aufwärmen auch die Mitte gut erhitzen.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/tartiflette-reblochon-kartoffeln\">Tartiflette mit Reblochon, Kartoffeln und Speck</a></li><li><a href=\"/de/rosmarin-focaccia-ohne-kneten\">Rosmarin-Focaccia ohne Kneten mit kalter Übernachtgare</a></li></ul>","content_html":"<p>Herzhafter Zwiebelkuchen mit selbst gemachtem Hefeboden, weich gedünsteten Zwiebeln, Speck und Kümmel. Für eine 28-cm-Springform und acht Stücke.</p><p>Die Gesamtzeit addiert alle Arbeitsschritte, auch wenn einige parallel möglich sind. Backhefe verwenden, kein Backpulver. Kümmel ist kein Kreuzkümmel; bei Bedarf weglassen statt beliebig ersetzen. Enthält Weizen, Milch und Ei. Reste innerhalb von 2 Stunden kühlen und innerhalb von 3 Tagen verbrauchen; beim Aufwärmen auch die Mitte gut erhitzen.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/tartiflette-reblochon-kartoffeln\">Tartiflette mit Reblochon, Kartoffeln und Speck</a></li><li><a href=\"/de/rosmarin-focaccia-ohne-kneten\">Rosmarin-Focaccia ohne Kneten mit kalter Übernachtgare</a></li></ul>","ingredients":[{"name":"Weizenmehl Type 405","amount":"300","unit":"g"},{"name":"Vollmilch","amount":"150","unit":"ml"},{"name":"Aktive Trockenhefe zum Backen","amount":"5","unit":"g"},{"name":"Zucker","amount":"5","unit":"g"},{"name":"Ungesalzene Butter","amount":"30","unit":"g"},{"name":"Salz für Teig und Füllung","amount":"6","unit":"g"},{"name":"Geschälte Zwiebeln","amount":"900","unit":"g"},{"name":"Gewürfelter Speck","amount":"100","unit":"g"},{"name":"Saure Sahne mit 18–20 % Fett","amount":"200","unit":"g"},{"name":"Eier, ohne Schale gewogen","amount":"100","unit":"g"},{"name":"Kümmelsamen","amount":"2","unit":"g"},{"name":"Gemahlener schwarzer Pfeffer","amount":"0.5","unit":"g"}],"steps":[{"title":"Teig kneten","content":"Mehl, Hefe, Zucker und 4 g Salz mischen. Lauwarme Milch und weiche Butter zugeben und 8–10 Minuten zu einem elastischen Teig kneten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Teig kneten"},{"title":"Gehen lassen","content":"Eine Kugel formen, die Schüssel abdecken und an einem warmen Ort etwa 60 Minuten gehen lassen, bis das Volumen deutlich zunimmt. Bei Kälte dauert es länger.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Gehen lassen"},{"title":"Füllung vorbereiten","content":"900 g Zwiebeln in dünne Streifen und den Speck in kleine Würfel schneiden. Die übrigen Zutaten abwiegen, bevor die Pfanne erhitzt wird.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Füllung vorbereiten"},{"title":"Zwiebeln garen und abkühlen","content":"Speck in einer großen Pfanne 5 Minuten anbraten. Zwiebeln zugeben und bei mittlerer bis kleiner Hitze etwa 15 Minuten weich, aber nicht dunkel garen. 10 Minuten abkühlen lassen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Zwiebeln garen und abkühlen"},{"title":"Form auslegen","content":"Den Boden einer 28-cm-Springform mit Backpapier belegen. Teig auf Boden und Seiten verteilen und einen 3 cm hohen Rand formen. 15 Minuten ruhen lassen; Ofen auf 180 °C vorheizen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Form auslegen"},{"title":"Guss mischen","content":"Ei, saure Sahne, Kümmel, Pfeffer und die übrigen 2 g Salz verquirlen. Die nur noch lauwarme Zwiebel-Speck-Mischung unterheben, keinesfalls heiß zugeben.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Guss mischen"},{"title":"Füllen und backen","content":"Füllung auf dem Teig verteilen. Bei 180 °C Ober-/Unterhitze 40–45 Minuten backen, bis die Mitte gestockt und der Boden durchgebacken ist. Zu schnell bräunenden Rand abdecken.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Füllen und backen"},{"title":"Ruhen und schneiden","content":"Vor dem Lösen der Form 10 Minuten warten. Mit einem Sägemesser in acht Stücke schneiden und warm mit saftiger, schnittfester Füllung servieren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne: Ruhen und schneiden"}],"category":"Brote und Teige","course":"Brote und Teige","cuisine":"Deutsch","difficulty":"Mittel","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne"}],"video_urls":[],"keywords":["Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne","Weizenmehl Type 405","Vollmilch"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"1 von 8 Portionen","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Referenzwerte nach Zutatengewicht summiert und durch die Portionen geteilt.","note":"Ungefähre Schätzung, keine Messung des fertigen Gerichts. Marken und Abtropfen verändern die Werte; unvollständige Nährstoffdaten werden nicht angezeigt. Generische Referenzen für Senf, Sahne, Süßkartoffeln, Öl und Schokolade; Sorten und Marken können abweichen."},"seo":{"title":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne","description":"Herzhafter Zwiebelkuchen mit selbst gemachtem Hefeboden, weich gedünsteten Zwiebeln, Speck und Kümmel. Für eine 28-cm-Springform und acht Stücke.","image_alt":"Zwiebelkuchen mit Hefeteig, Speck und saurer Sahne","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"Kann ich Blätterteig verwenden?","a":"Diese Mengen sind für Hefeteig ausgelegt. Blätterteig ergibt einen anderen Boden und braucht andere Zeiten; er ist kein direkter Ersatz."},{"q":"Müssen die Zwiebeln karamellisieren?","a":"Nein. Sie sollen weich und hell bleiben. Dunkles Bräunen verändert den Geschmack und kann die Füllung austrocknen."},{"q":"Kann ich den Kuchen am Vortag backen?","a":"Ja. Backen, abkühlen und abgedeckt kühlen. Stückweise aufwärmen; rohe Eierfüllung nicht bei Zimmertemperatur stehen lassen."}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"german-onion-cake-zwiebelkuchen","public_path":"/en/german-onion-cake-zwiebelkuchen","title":"Zwiebelkuchen: German onion cake with yeast dough","excerpt":"A savoury German onion tart with a soft yeast base, slowly softened onions, bacon, sour cream and caraway. Make one 28 cm tart to cut into eight portions.","summary":"A savoury German onion tart with a soft yeast base, slowly softened onions, bacon, sour cream and caraway. Make one 28 cm tart to cut into eight portions.","notes":"<p>Use baker’s yeast, not baking powder, and caraway, not cumin. Contains wheat, milk and eggs. The stated total allows for rising, filling cooling, the second dough rest and resting after baking; some tasks overlap. Refrigerate within 2 hours and use within 3 days. Nutrition counts the rendered bacon fat retained in the filling; any accompanying salad is excluded.</p><h2>You may also like</h2><ul><li><a href=\"/en/reblochon-tartiflette\">Reblochon tartiflette with potatoes and bacon</a></li><li><a href=\"/en/no-knead-rosemary-focaccia\">No-knead rosemary focaccia with an overnight rise</a></li></ul>","content_html":"<p>A savoury German onion tart with a soft yeast base, slowly softened onions, bacon, sour cream and caraway. Make one 28 cm tart to cut into eight portions.</p><p>Use baker’s yeast, not baking powder, and caraway, not cumin. Contains wheat, milk and eggs. The stated total allows for rising, filling cooling, the second dough rest and resting after baking; some tasks overlap. Refrigerate within 2 hours and use within 3 days. Nutrition counts the rendered bacon fat retained in the filling; any accompanying salad is excluded.</p><h2>You may also like</h2><ul><li><a href=\"/en/reblochon-tartiflette\">Reblochon tartiflette with potatoes and bacon</a></li><li><a href=\"/en/no-knead-rosemary-focaccia\">No-knead rosemary focaccia with an overnight rise</a></li></ul>","ingredients":[{"name":"All-purpose wheat flour","amount":"300","unit":"g"},{"name":"Whole milk","amount":"150","unit":"ml"},{"name":"Active dry baker’s yeast","amount":"5","unit":"g"},{"name":"Sugar","amount":"5","unit":"g"},{"name":"Unsalted butter","amount":"30","unit":"g"},{"name":"Salt","amount":"6","unit":"g"},{"name":"Peeled onions","amount":"900","unit":"g"},{"name":"Bacon","amount":"100","unit":"g"},{"name":"Sour cream, 18–20% fat","amount":"200","unit":"g"},{"name":"Eggs, weighed without shells","amount":"100","unit":"g"},{"name":"Caraway seeds","amount":"2","unit":"g"},{"name":"Ground black pepper","amount":"0.5","unit":"g"}],"steps":[{"title":"Knead the dough","content":"Mix flour, lukewarm milk, yeast, sugar, softened butter and 4 g salt. Knead for 8–10 minutes until smooth; the milk must not be hot.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Knead the dough"},{"title":"Let it rise","content":"Cover the dough in a bowl and leave in a warm, draught-free place for about 60 minutes, until roughly doubled in volume.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Let it rise"},{"title":"Prepare the filling","content":"Thinly slice the 900 g peeled onions and dice the bacon. Weigh the sour cream and 100 g egg without shells; keep them chilled until mixing.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Prepare the filling"},{"title":"Cook and cool the onions","content":"Cook the bacon in a wide pan for 5 minutes. Add the onions and cook gently for 15 minutes, stirring until soft. Take off the heat and cool for 10 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Cook and cool the onions"},{"title":"Line the tin","content":"Roll out the dough and line a 28 cm springform tin, making a 3 cm rim. Rest for 15 minutes while preheating the oven to 180 °C, conventional heat.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Line the tin"},{"title":"Mix the filling","content":"Whisk eggs, sour cream, caraway, pepper and the remaining 2 g salt. Fold in the cooled onion and bacon mixture and spread over the dough.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Mix the filling"},{"title":"Bake","content":"Bake at 180 °C for 40–45 minutes until the base is cooked and the centre is set. Cover the rim if browning too quickly; extend cooking if the filling is still liquid.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Bake"},{"title":"Rest and slice","content":"Rest in the tin for 10 minutes, then carefully release the sides and cut into eight portions. Serve warm with a simple salad if desired.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"Zwiebelkuchen: German onion cake with yeast dough: Rest and slice"}],"category":"Breads & doughs","course":"Breads & doughs","cuisine":"German","difficulty":"Medium","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"Zwiebelkuchen: German onion cake with yeast dough"}],"video_urls":[],"keywords":["Zwiebelkuchen: German onion cake with yeast dough","All-purpose wheat flour","Whole milk"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"1 of 8 servings","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Reference nutrients summed by ingredient weight and divided by servings.","note":"Approximate estimate, not a measurement of the cooked dish. Brands and draining change values; nutrients with incomplete data are omitted. Generic references for prepared mustard, cream, sweet potato, oil and chocolate; specific varieties and brands can differ."},"seo":{"title":"Zwiebelkuchen: German onion cake with yeast dough","description":"A savoury German onion tart with a soft yeast base, slowly softened onions, bacon, sour cream and caraway. Make one 28 cm tart to cut into eight portions.","image_alt":"Zwiebelkuchen: German onion cake with yeast dough","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"Can I make Zwiebelkuchen ahead?","a":"Yes. Refrigerate the baked tart and reheat portions in the oven until hot throughout. The base is best on the first day."},{"q":"Why cook the onions first?","a":"It softens them, removes some water and prevents a wet filling with raw onion inside."},{"q":"Can I omit the bacon?","a":"Yes, but use a little additional fat to soften the onions. That variation changes the flavour and the calculated nutrition."}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"zwiebelkuchen-tarte-allemande-oignons","public_path":"/fr/zwiebelkuchen-tarte-allemande-oignons","title":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée","excerpt":"Une tarte allemande aux oignons, lardons, crème aigre et carvi sur une pâte levée maison. Pour un moule de 28 cm et huit parts, avec les repos inclus.","summary":"Une tarte allemande aux oignons, lardons, crème aigre et carvi sur une pâte levée maison. Pour un moule de 28 cm et huit parts, avec les repos inclus.","notes":"<p>Le total additionne les étapes sans déduire les tâches réalisables en parallèle. Utilisez de la levure boulangère, pas de levure chimique. Le carvi n’est pas du cumin ; mieux vaut l’omettre que le remplacer sans adaptation. Contient blé, lait et œuf. Réfrigérez avant 2 heures et consommez sous 3 jours ; réchauffez bien le centre.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/tartiflette-reblochon\">Tartiflette au reblochon, pommes de terre et lardons</a></li><li><a href=\"/fr/focaccia-romarin-sans-petrissage\">Focaccia au romarin sans pétrissage, levée au froid</a></li></ul>","content_html":"<p>Une tarte allemande aux oignons, lardons, crème aigre et carvi sur une pâte levée maison. Pour un moule de 28 cm et huit parts, avec les repos inclus.</p><p>Le total additionne les étapes sans déduire les tâches réalisables en parallèle. Utilisez de la levure boulangère, pas de levure chimique. Le carvi n’est pas du cumin ; mieux vaut l’omettre que le remplacer sans adaptation. Contient blé, lait et œuf. Réfrigérez avant 2 heures et consommez sous 3 jours ; réchauffez bien le centre.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/tartiflette-reblochon\">Tartiflette au reblochon, pommes de terre et lardons</a></li><li><a href=\"/fr/focaccia-romarin-sans-petrissage\">Focaccia au romarin sans pétrissage, levée au froid</a></li></ul>","ingredients":[{"name":"Farine de blé courante","amount":"300","unit":"g"},{"name":"Lait entier","amount":"150","unit":"ml"},{"name":"Levure boulangère sèche active","amount":"5","unit":"g"},{"name":"Sucre","amount":"5","unit":"g"},{"name":"Beurre doux","amount":"30","unit":"g"},{"name":"Sel pour la pâte et la garniture","amount":"6","unit":"g"},{"name":"Oignons épluchés","amount":"900","unit":"g"},{"name":"Poitrine fumée en dés","amount":"100","unit":"g"},{"name":"Crème aigre à 18–20 % de matière grasse","amount":"200","unit":"g"},{"name":"Œufs, pesés sans coquille","amount":"100","unit":"g"},{"name":"Graines de carvi","amount":"2","unit":"g"},{"name":"Poivre noir moulu","amount":"0.5","unit":"g"}],"steps":[{"title":"Pétrir la pâte","content":"Mélangez farine, levure, sucre et 4 g de sel. Incorporez le lait tiède et le beurre mou ; pétrissez 8–10 minutes pour obtenir une pâte élastique.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Pétrir la pâte"},{"title":"Laisser lever","content":"Formez une boule, couvrez le saladier et laissez lever environ 60 minutes dans un endroit tiède, jusqu’à une nette augmentation du volume. Le froid prolonge ce temps.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Laisser lever"},{"title":"Découper la garniture","content":"Émincez les 900 g d’oignons et coupez la poitrine en petits dés. Pesez les autres ingrédients avant de chauffer la poêle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Découper la garniture"},{"title":"Cuire et tiédir les oignons","content":"Faites dorer la poitrine 5 minutes dans une grande poêle. Ajoutez les oignons et faites-les fondre à feu moyen-doux environ 15 minutes, sans coloration foncée. Laissez tiédir 10 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Cuire et tiédir les oignons"},{"title":"Foncer le moule","content":"Tapissez de papier cuisson le fond d’un moule à charnière de 28 cm. Garnissez fond et côtés de pâte, avec un bord de 3 cm. Reposez 15 minutes et préchauffez à 180 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Foncer le moule"},{"title":"Mélanger l’appareil","content":"Battez les œufs avec crème aigre, carvi, poivre et 2 g de sel restants. Incorporez les oignons et lardons tièdes, jamais très chauds.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Mélanger l’appareil"},{"title":"Garnir et cuire","content":"Répartissez l’appareil sur la pâte. Enfournez à 180 °C, chaleur statique, pour 40–45 minutes, jusqu’à ce que le centre soit pris et le fond cuit. Protégez le bord s’il colore trop vite.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Garnir et cuire"},{"title":"Reposer et découper","content":"Attendez 10 minutes avant de démouler. Coupez huit parts avec un couteau dentelé et servez tiède, avec une garniture ferme et moelleuse.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée: Reposer et découper"}],"category":"Pains et pâtes","course":"Pains et pâtes","cuisine":"Allemande","difficulty":"Moyenne","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée"}],"video_urls":[],"keywords":["Zwiebelkuchen : tarte allemande aux oignons sur pâte levée","Farine de blé courante","Lait entier"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"1 des 8 portions","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des références selon le poids des ingrédients, divisée par le nombre de portions.","note":"Estimation indicative, pas une mesure du plat cuisiné. Marques et égouttage changent les valeurs ; les nutriments incomplets ne sont pas affichés. Références génériques pour moutarde préparée, crème, patate douce, huile et chocolat ; variétés et marques peuvent différer."},"seo":{"title":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée","description":"Une tarte allemande aux oignons, lardons, crème aigre et carvi sur une pâte levée maison. Pour un moule de 28 cm et huit parts, avec les repos inclus.","image_alt":"Zwiebelkuchen : tarte allemande aux oignons sur pâte levée","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"Puis-je utiliser une pâte feuilletée ?","a":"Cette formulation utilise une pâte levée. Une pâte feuilletée donne un fond différent et demande d’autres temps ; ce n’est pas un remplacement direct."},{"q":"Faut-il caraméliser les oignons ?","a":"Non. Ils doivent rester tendres et clairs. Une coloration foncée change le goût et peut dessécher la garniture."},{"q":"Peut-on préparer la tarte la veille ?","a":"Oui. Faites cuire, refroidissez puis réfrigérez à couvert. Réchauffez les parts ; ne laissez pas l’appareil aux œufs crus à température ambiante."}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"zwiebelkuchen-torta-tedesca-cipolle","public_path":"/it/zwiebelkuchen-torta-tedesca-cipolle","title":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato","excerpt":"Torta salata tedesca con base lievitata, cipolle stufate, pancetta affumicata e panna acida. Dosi per uno stampo da 28 cm e otto porzioni, con riposi inclusi.","summary":"Torta salata tedesca con base lievitata, cipolle stufate, pancetta affumicata e panna acida. Dosi per uno stampo da 28 cm e otto porzioni, con riposi inclusi.","notes":"<p>Il totale somma le fasi senza sottrarre le operazioni sovrapponibili. Usa lievito di birra, non lievito istantaneo per torte. Il carvi non è cumino: se manca, omettilo invece di sostituirlo automaticamente. Contiene frumento, latte e uova. Metti in frigorifero entro 2 ore e consuma entro 3 giorni; riscalda bene anche il centro.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/tartiflette-reblochon-patate\">Tartiflette con patate, reblochon e pancetta affumicata</a></li><li><a href=\"/it/focaccia-rosmarino-senza-impasto\">Focaccia al rosmarino senza impasto, con lievitazione in frigo</a></li></ul>","content_html":"<p>Torta salata tedesca con base lievitata, cipolle stufate, pancetta affumicata e panna acida. Dosi per uno stampo da 28 cm e otto porzioni, con riposi inclusi.</p><p>Il totale somma le fasi senza sottrarre le operazioni sovrapponibili. Usa lievito di birra, non lievito istantaneo per torte. Il carvi non è cumino: se manca, omettilo invece di sostituirlo automaticamente. Contiene frumento, latte e uova. Metti in frigorifero entro 2 ore e consuma entro 3 giorni; riscalda bene anche il centro.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/tartiflette-reblochon-patate\">Tartiflette con patate, reblochon e pancetta affumicata</a></li><li><a href=\"/it/focaccia-rosmarino-senza-impasto\">Focaccia al rosmarino senza impasto, con lievitazione in frigo</a></li></ul>","ingredients":[{"name":"Farina di frumento comune","amount":"300","unit":"g"},{"name":"Latte intero","amount":"150","unit":"ml"},{"name":"Lievito di birra secco attivo","amount":"5","unit":"g"},{"name":"Zucchero","amount":"5","unit":"g"},{"name":"Burro non salato","amount":"30","unit":"g"},{"name":"Sale per impasto e ripieno","amount":"6","unit":"g"},{"name":"Cipolle sbucciate","amount":"900","unit":"g"},{"name":"Pancetta affumicata a dadini","amount":"100","unit":"g"},{"name":"Panna acida al 18–20% di grassi","amount":"200","unit":"g"},{"name":"Uova, pesate senza guscio","amount":"100","unit":"g"},{"name":"Semi di carvi","amount":"2","unit":"g"},{"name":"Pepe nero macinato","amount":"0.5","unit":"g"}],"steps":[{"title":"Impasta la base","content":"Mescola farina, lievito, zucchero e 4 g di sale. Unisci latte tiepido e burro morbido; impasta per 8–10 minuti fino a ottenere un impasto elastico.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Impasta la base"},{"title":"Lascia lievitare","content":"Forma una palla, copri la ciotola e lascia lievitare circa 60 minuti in un luogo tiepido, finché il volume aumenta chiaramente. Il freddo può allungare il tempo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Lascia lievitare"},{"title":"Taglia il ripieno","content":"Affetta finemente i 900 g di cipolle e taglia la pancetta a dadini. Pesa gli altri ingredienti prima di scaldare la padella.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Taglia il ripieno"},{"title":"Cuoci e intiepidisci","content":"Rosola la pancetta per 5 minuti in una padella ampia. Aggiungi le cipolle e cuoci a fuoco medio-basso per circa 15 minuti, senza scurirle. Lascia intiepidire 10 minuti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Cuoci e intiepidisci"},{"title":"Rivesti lo stampo","content":"Metti carta da forno sul fondo di uno stampo a cerniera da 28 cm. Rivesti base e lati con l’impasto, formando un bordo di 3 cm. Riposa 15 minuti e preriscalda a 180 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Rivesti lo stampo"},{"title":"Prepara la crema","content":"Sbatti uova, panna acida, carvi, pepe e i 2 g di sale rimasti. Incorpora cipolle e pancetta ormai tiepide, mai bollenti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Prepara la crema"},{"title":"Farcisci e inforna","content":"Distribuisci il ripieno sull’impasto. Cuoci a 180 °C, forno statico, per 40–45 minuti, finché il centro è rappreso e la base cotta. Proteggi il bordo se scurisce prima.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Farcisci e inforna"},{"title":"Riposa e taglia","content":"Aspetta 10 minuti prima di sformare. Taglia otto porzioni con un coltello seghettato e servi tiepido, con ripieno compatto e morbido.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato: Riposa e taglia"}],"category":"Pane e impasti","course":"Pane e impasti","cuisine":"Tedesca","difficulty":"Media","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato"}],"video_urls":[],"keywords":["Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato","Farina di frumento comune","Latte intero"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"1 di 8 porzioni","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somma dei valori di riferimento per peso, divisa per le porzioni.","note":"Stima indicativa, non misurazione del piatto cotto. Marche e scolatura modificano i valori; nutrienti con dati incompleti non sono mostrati. Riferimenti generici per senape preparata, panna, patata dolce, olio e cioccolato; varietà e marche possono differire."},"seo":{"title":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato","description":"Torta salata tedesca con base lievitata, cipolle stufate, pancetta affumicata e panna acida. Dosi per uno stampo da 28 cm e otto porzioni, con riposi inclusi.","image_alt":"Zwiebelkuchen: torta tedesca di cipolle con impasto lievitato","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"Posso usare pasta sfoglia?","a":"Questa formulazione usa una base lievitata. La sfoglia dà un risultato diverso e richiede altri tempi; non è una sostituzione diretta."},{"q":"Devo caramellare le cipolle?","a":"No. Devono diventare tenere restando chiare. Una forte doratura cambia il sapore e può asciugare il ripieno."},{"q":"Posso prepararla il giorno prima?","a":"Sì. Cuoci, raffredda e conserva coperta in frigorifero. Riscalda le porzioni e non lasciare il ripieno con uova crude a temperatura ambiente."}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"zwiebelkuchen-onion-tart","public_path":"/ja/zwiebelkuchen-onion-tart","title":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト","excerpt":"発酵させた自家製生地に、柔らかい玉ねぎ、ベーコン、サワークリームを詰めるドイツのタルト。28 cm型1台、8切れ分で、発酵と休ませる時間も含みます。","summary":"発酵させた自家製生地に、柔らかい玉ねぎ、ベーコン、サワークリームを詰めるドイツのタルト。28 cm型1台、8切れ分で、発酵と休ませる時間も含みます。","notes":"<p>総時間は、同時進行できる工程も差し引かずに合計しています。ベーキングパウダーではなく製パン用イーストを使います。キャラウェイはクミンとは違い、なければ省いてください。小麦、乳、卵を含みます。残りは2時間以内に冷蔵し、3日以内に食べ、中心まで十分に温め直します。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/reblochon-tartiflette\">ルブロションのタルティフレット</a></li><li><a href=\"/ja/no-knead-rosemary-focaccia\">こねないローズマリーフォカッチャ：冷蔵庫で一晩発酵</a></li></ul>","content_html":"<p>発酵させた自家製生地に、柔らかい玉ねぎ、ベーコン、サワークリームを詰めるドイツのタルト。28 cm型1台、8切れ分で、発酵と休ませる時間も含みます。</p><p>総時間は、同時進行できる工程も差し引かずに合計しています。ベーキングパウダーではなく製パン用イーストを使います。キャラウェイはクミンとは違い、なければ省いてください。小麦、乳、卵を含みます。残りは2時間以内に冷蔵し、3日以内に食べ、中心まで十分に温め直します。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/reblochon-tartiflette\">ルブロションのタルティフレット</a></li><li><a href=\"/ja/no-knead-rosemary-focaccia\">こねないローズマリーフォカッチャ：冷蔵庫で一晩発酵</a></li></ul>","ingredients":[{"name":"小麦粉（中力粉）","amount":"300","unit":"g"},{"name":"牛乳（全乳）","amount":"150","unit":"ml"},{"name":"製パン用アクティブドライイースト","amount":"5","unit":"g"},{"name":"砂糖","amount":"5","unit":"g"},{"name":"無塩バター","amount":"30","unit":"g"},{"name":"塩（生地と具に分ける）","amount":"6","unit":"g"},{"name":"玉ねぎ（皮を除く）","amount":"900","unit":"g"},{"name":"ベーコン（角切り）","amount":"100","unit":"g"},{"name":"サワークリーム（乳脂肪18〜20%）","amount":"200","unit":"g"},{"name":"卵（殻を除いて量る）","amount":"100","unit":"g"},{"name":"キャラウェイシード","amount":"2","unit":"g"},{"name":"黒こしょう（粉）","amount":"0.5","unit":"g"}],"steps":[{"title":"生地をこねる","content":"小麦粉、イースト、砂糖、塩4 gを混ぜます。ぬるい牛乳と柔らかいバターを加え、弾力が出るまで8〜10分こねます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 生地をこねる"},{"title":"発酵させる","content":"丸めてボウルに入れ、覆って温かい場所で約60分、体積がはっきり増えるまで発酵させます。寒い場所では長くかかります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 発酵させる"},{"title":"具を切る","content":"玉ねぎ900 gを薄切りにし、ベーコンを小さな角切りにします。フライパンを熱する前に残りの材料も量ります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 具を切る"},{"title":"玉ねぎを炒めて冷ます","content":"大きなフライパンでベーコンを5分炒めます。玉ねぎを加え、中弱火で約15分、濃い色にせず柔らかくします。10分冷まします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 玉ねぎを炒めて冷ます"},{"title":"型に生地を敷く","content":"底にオーブンペーパーを敷いた28 cmの底が外れる型に、生地を底面と側面へ広げます。高さ3 cmの縁を作り15分休ませ、オーブンを180 °Cに予熱します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 型に生地を敷く"},{"title":"卵液を混ぜる","content":"卵、サワークリーム、キャラウェイ、こしょう、残りの塩2 gを混ぜます。玉ねぎとベーコンがぬるくなってから加え、熱いまま入れません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 卵液を混ぜる"},{"title":"詰めて焼く","content":"具を生地に広げ、180 °Cの上下加熱で40〜45分焼きます。中心が固まり底まで焼けたら完成です。縁が先に色付いたら覆います。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 詰めて焼く"},{"title":"休ませて切る","content":"10分置いてから型を外します。波刃のナイフで8等分し、具が固まりつつしっとりした状態で温かく出します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト: 休ませて切る"}],"category":"パン・生地料理","course":"パン・生地料理","cuisine":"ドイツ料理","difficulty":"中級","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト"}],"video_urls":[],"keywords":["ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト","小麦粉（中力粉）","牛乳（全乳）"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"全8人分のうち1人分","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"材料の重量に応じた参考栄養値を合計し、人数で割っています。","note":"調理済み料理の実測値ではなく概算です。商品や水切りで変わり、資料がそろわない栄養素は表示しません。 マスタード、生クリーム、さつまいも、油、チョコレートは一般的な参考値を使用し、品種や商品で異なります。"},"seo":{"title":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト","description":"発酵させた自家製生地に、柔らかい玉ねぎ、ベーコン、サワークリームを詰めるドイツのタルト。28 cm型1台、8切れ分で、発酵と休ませる時間も含みます。","image_alt":"ツヴィーベルクーヘン：発酵生地で作るドイツの玉ねぎタルト","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"パイシートを使えますか？","a":"この分量は発酵生地向けです。パイシートでは土台も焼成時間も変わるため、そのままの置き換えにはなりません。"},{"q":"玉ねぎはあめ色にしますか？","a":"いいえ。柔らかく、淡い色に仕上げます。濃く焼くと味が変わり、具が乾くことがあります。"},{"q":"前日に作れますか？","a":"焼いて冷まし、覆って冷蔵できます。切り分けて再加熱します。生卵入りの具を室温に放置しないでください。"}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"zwiebelkuchen-torta-alema-cebola","public_path":"/pt/zwiebelkuchen-torta-alema-cebola","title":"Zwiebelkuchen: torta alemã de cebola com massa fermentada","excerpt":"Torta alemã de cebola com massa caseira de fermento biológico, bacon e creme azedo. Para uma forma de 28 cm e oito fatias, com fermentação e descansos incluídos.","summary":"Torta alemã de cebola com massa caseira de fermento biológico, bacon e creme azedo. Para uma forma de 28 cm e oito fatias, com fermentação e descansos incluídos.","notes":"<p>O total soma todas as etapas sem descontar tarefas simultâneas. Use fermento biológico, não fermento químico. Alcarávia não é cominho: se não encontrar, omita em vez de trocar automaticamente. Contém trigo, leite e ovos. Refrigere antes de 2 horas e consuma em até 3 dias; reaqueça bem o centro.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/tartiflette-reblochon-batatas\">Tartiflette de batata com reblochon e bacon</a></li><li><a href=\"/pt/focaccia-alecrim-sem-sovar\">Focaccia de alecrim sem sovar, com fermentação na geladeira</a></li></ul>","content_html":"<p>Torta alemã de cebola com massa caseira de fermento biológico, bacon e creme azedo. Para uma forma de 28 cm e oito fatias, com fermentação e descansos incluídos.</p><p>O total soma todas as etapas sem descontar tarefas simultâneas. Use fermento biológico, não fermento químico. Alcarávia não é cominho: se não encontrar, omita em vez de trocar automaticamente. Contém trigo, leite e ovos. Refrigere antes de 2 horas e consuma em até 3 dias; reaqueça bem o centro.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/tartiflette-reblochon-batatas\">Tartiflette de batata com reblochon e bacon</a></li><li><a href=\"/pt/focaccia-alecrim-sem-sovar\">Focaccia de alecrim sem sovar, com fermentação na geladeira</a></li></ul>","ingredients":[{"name":"Farinha de trigo comum","amount":"300","unit":"g"},{"name":"Leite integral","amount":"150","unit":"ml"},{"name":"Fermento biológico seco ativo","amount":"5","unit":"g"},{"name":"Açúcar","amount":"5","unit":"g"},{"name":"Manteiga sem sal","amount":"30","unit":"g"},{"name":"Sal para massa e recheio","amount":"6","unit":"g"},{"name":"Cebolas descascadas","amount":"900","unit":"g"},{"name":"Bacon em cubinhos","amount":"100","unit":"g"},{"name":"Creme azedo com 18–20% de gordura","amount":"200","unit":"g"},{"name":"Ovos, pesados sem casca","amount":"100","unit":"g"},{"name":"Sementes de alcarávia","amount":"2","unit":"g"},{"name":"Pimenta-do-reino moída","amount":"0.5","unit":"g"}],"steps":[{"title":"Sove a massa","content":"Misture farinha, fermento, açúcar e 4 g de sal. Junte leite morno e manteiga macia; sove por 8–10 minutos até obter uma massa elástica.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-01.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Sove a massa"},{"title":"Deixe crescer","content":"Forme uma bola, cubra a tigela e deixe fermentar por cerca de 60 minutos em local morno, até aumentar claramente de volume. O frio pode alongar esse tempo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-02.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Deixe crescer"},{"title":"Corte o recheio","content":"Corte os 900 g de cebolas em tiras finas e o bacon em cubinhos. Pese os demais ingredientes antes de aquecer a frigideira.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-03.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Corte o recheio"},{"title":"Cozinhe e esfrie a cebola","content":"Doure o bacon por 5 minutos numa frigideira grande. Junte as cebolas e cozinhe em fogo médio-baixo por cerca de 15 minutos, sem escurecer. Deixe amornar por 10 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-04.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Cozinhe e esfrie a cebola"},{"title":"Forre a forma","content":"Forre o fundo de uma forma de aro removível de 28 cm com papel-manteiga. Distribua a massa no fundo e laterais, com borda de 3 cm. Descanse 15 minutos e preaqueça a 180 °C.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-05.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Forre a forma"},{"title":"Misture o creme","content":"Bata os ovos com creme azedo, alcarávia, pimenta e os 2 g de sal restantes. Incorpore cebola e bacon mornos, nunca muito quentes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-06.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Misture o creme"},{"title":"Recheie e asse","content":"Espalhe o recheio sobre a massa. Asse a 180 °C, forno convencional, por 40–45 minutos, até o centro firmar e a base cozinhar. Proteja a borda se dourar antes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-07.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Recheie e asse"},{"title":"Descanse e corte","content":"Espere 10 minutos antes de desenformar. Corte oito fatias com faca serrilhada e sirva morno, com recheio firme e úmido.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/paso-08.webp","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada: Descanse e corte"}],"category":"Pães e massas","course":"Pães e massas","cuisine":"Alemã","difficulty":"Média","prep_time_minutes":35,"cook_time_minutes":65,"total_time_minutes":195,"servings":8,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada.webp","alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada"}],"video_urls":[],"keywords":["Zwiebelkuchen: torta alemã de cebola com massa fermentada","Farinha de trigo comum","Leite integral"],"nutrition":{"calories":342,"protein_g":9.9,"carbs_g":42.3,"fat_g":14.9,"saturated_fat_g":6.9,"fiber_g":3.2,"sugar_g":7.4,"sodium_mg":424.0,"estimated":true,"serving_size":"1 das 8 porções","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Soma das referências pelo peso dos ingredientes, dividida pelas porções.","note":"Estimativa orientativa, não medição do prato pronto. Marcas e escorrimento alteram os valores; nutrientes com dados incompletos não são mostrados. Referências genéricas para mostarda preparada, creme, batata-doce, óleo e chocolate; variedades e marcas podem diferir."},"seo":{"title":"Zwiebelkuchen: torta alemã de cebola com massa fermentada","description":"Torta alemã de cebola com massa caseira de fermento biológico, bacon e creme azedo. Para uma forma de 28 cm e oito fatias, com fermentação e descansos incluídos.","image_alt":"Zwiebelkuchen: torta alemã de cebola com massa fermentada","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/zwiebelkuchen-tarta-cebolla/portada-16x9.webp"],"faq":[{"q":"Posso usar massa folhada?","a":"Esta formulação usa massa fermentada. A folhada cria outra base e precisa de outros tempos; não é uma troca direta."},{"q":"Preciso caramelizar a cebola?","a":"Não. Ela deve ficar macia e clara. Dourar demais muda o sabor e pode ressecar o recheio."},{"q":"Posso fazer na véspera?","a":"Sim. Asse, esfrie e refrigere coberto. Reaqueça as fatias; não deixe o recheio com ovos crus em temperatura ambiente."}],"rest_time_minutes":95},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null}]$payload$::jsonb; aliases jsonb := $aliases$[{"alias":"Harina de trigo común","slug":"harina-de-trigo"},{"alias":"Leche entera","slug":"leche"},{"alias":"Levadura seca de panadería","slug":"levadura-seca"},{"alias":"Azúcar","slug":"azucar"},{"alias":"Mantequilla sin sal","slug":"mantequilla"},{"alias":"Sal, repartida entre masa y relleno","slug":"sal"},{"alias":"Cebolla pelada","slug":"cebolla"},{"alias":"Tocineta en dados","slug":"tocineta"},{"alias":"Crema agria con 18–20 % de grasa","slug":"crema-agria"},{"alias":"Huevos, peso sin cáscara","slug":"huevo"},{"alias":"Semillas de alcaravea","slug":"alcaravea"},{"alias":"Pimienta negra molida","slug":"pimienta-negra"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; n int:=0; previous_links jsonb;
BEGIN
SELECT coalesce(jsonb_agg(jsonb_build_array(ri.recipe_id,ri.ingredient_id,ri.amount,ri.unit,ri.preparation,ri.note,ri.position)),'[]'::jsonb) INTO previous_links FROM public.recipe_ingredients ri JOIN public.ingredients i ON i.id=ri.ingredient_id WHERE i.status='canonical';
IF jsonb_array_length(j)<>7 THEN RAISE EXCEPTION 'Expected 7 records'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe collision; no rows created'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(j) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'URL collision; no rows created'; END IF;
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias)
 SELECT i.id,a->>'alias',lower(trim(a->>'alias')) FROM public.ingredients i
 WHERE i.slug=a->>'slug' AND i.status='canonical' AND i.searchable
 AND NOT EXISTS(SELECT 1 FROM public.ingredient_aliases ia WHERE ia.ingredient_id=i.id AND lower(trim(ia.alias))=lower(trim(a->>'alias')));
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;
 ELSE
  IF source_id IS NULL THEN RAISE EXCEPTION 'Spanish source required'; END IF;
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo WHERE id=made.id;
 n:=n+1;
END LOOP;
IF n<>7 THEN RAISE EXCEPTION 'Expected 7 creates'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(previous_links) e WHERE NOT EXISTS(SELECT 1 FROM public.recipe_ingredients ri WHERE ri.recipe_id=(e->>0)::uuid AND ri.ingredient_id=(e->>1)::uuid AND ri.amount IS NOT DISTINCT FROM e->>2 AND ri.unit IS NOT DISTINCT FROM e->>3 AND ri.preparation IS NOT DISTINCT FROM e->>4 AND ri.note IS NOT DISTINCT FROM e->>5 AND ri.position=(e->>6)::int)) THEN RAISE EXCEPTION 'Existing canonical link changed'; END IF;
END $stage$;
SELECT recipe_group_id,language,public_path,published FROM public.recipes WHERE public_path IN ('/zwiebelkuchen-tarta-cebolla','/de/zwiebelkuchen-hefeteig-speck','/en/german-onion-cake-zwiebelkuchen','/fr/zwiebelkuchen-tarte-allemande-oignons','/it/zwiebelkuchen-torta-tedesca-cipolle','/ja/zwiebelkuchen-onion-tart','/pt/zwiebelkuchen-torta-alema-cebola') ORDER BY language;
